// Output of the mood classifier: line 1 = mood, line 2 = confidence (1-10)
const raw = String($json.text || '').toLowerCase();

const labelMatch = raw.match(/urgent|frustrated|angry|confused|happy|sad|neutral/);
let label = labelMatch ? labelMatch[0] : 'neutral';
if (label === 'angry') label = 'frustrated'; // moods: urgent, frustrated, confused, happy, neutral
if (label === 'sad') label = 'neutral';

const confMatch = raw.match(/\d+/);
const confidence = confMatch ? Number(confMatch[0]) : 0;

// Only trust the mood label (including urgent) if confidence >= 7, otherwise neutral
let mood = confidence >= 7 ? label : 'neutral';

// Keyword guard for urgency: the small model sometimes calls "URGENT: ..." just frustrated, so a message that
// literally says it is urgent is always treated as urgent, whatever the model answered.
const msgText = String($('Telegram Trigger').first().json.message.text || '');
const urgentByKeyword = /\b(urgent(ly)?|asap|emergency|immediately)\b|عاجل|عاجلة|فورا|فوراً|ضروري جدا|ضروري جداً/i.test(msgText);
if (urgentByKeyword) mood = 'urgent';

const category = String($('Basic LLM Chain').item.json.text || '').trim().toLowerCase().replace(/[^a-z ]/g, '');

return { json: { Category: category, mood, confidence, raw_mood: label, urgent_by_keyword: urgentByKeyword } };

