const m = $json.message || {};
let kind = 'blank';
if (m.photo) kind = 'image';
else if (m.voice) kind = 'voice note';
else if (m.audio) kind = 'audio file';
else if (m.sticker) kind = 'sticker';
else if (m.video || m.video_note || m.animation) kind = 'video';
else if (m.document) kind = 'file';
else if (m.location || m.contact || m.poll) kind = 'attachment';
const name = (m.chat && m.chat.first_name) || 'there';
const reply = kind === 'blank'
  ? 'Hi ' + name + ', your message looks empty. Please type your question in words and I will help you.'
  : 'Hi ' + name + ', I received your ' + kind + ', but I can only read text messages. Please type your question in words and I will help you.';
return { json: { kind, reply } };

// Only these five categories are valid. Anything else becomes 'other'.
const VALID = ['grade', 'registration', 'payment', 'schedule', 'other'];
const original = $json.Category;
const cleaned = String(original === undefined || original === null ? '' : original).trim().toLowerCase();
const isValid = VALID.includes(cleaned);
return { json: { ...$json, Category: isValid ? cleaned : 'other', original_category: original === undefined ? null : original, category_was_valid: isValid } };

const rows = $input.all().map(i => i.json).filter(r => r['Student Id'] !== undefined && String(r['Student Id']).trim() !== '');
const existing = rows.length ? rows[0] : null;
const count = existing ? (Number(existing.Count) || 1) + 1 : 1;
const chat = $('Telegram Trigger').first().json.message.chat;
return [{ json: { 'Student Id': String(chat.id), Key: String(chat.id) + '|other', Category: 'other', Count: String(count), Priority: 'HIGH', Date: $now.toISO(), isDuplicate: !!existing } }];

// Turn this student's earlier rows of the conversation log into a short history text for the AI (the latest earlier message),
// and let a short follow-up ("Is there a deadline for it?") inherit the topic of the previous message.
const v = $('Validate Category').first().json;               // category and mood of the current message
const tg = $('Telegram Trigger').first().json.message;
const chat = tg.chat;
const text = String(tg.text || '');

// A bare greeting or thank-you ("Hello there", "thanks") does not continue any earlier topic.
// The small AI model answers the old topic again when it sees history for such a message,
// so the history is left out for it, and greetings are also not kept as history.
const GREET = ['hi', 'hello', 'hey', 'hola', 'thanks', 'thank', 'ok', 'okay', 'good', 'مرحبا', 'اهلا', 'أهلا', 'هلا', 'شكرا', 'شكراً', 'السلام'];
const wordsOf = (t) => String(t).toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(Boolean);
const isGreetingText = (t) => { const w = wordsOf(t); return w.length > 0 && w.length <= 4 && GREET.includes(w[0]); };
const isGreeting = isGreetingText(text);

// Short follow-ups that point back ("Is there a deadline for it?") say nothing about the topic themselves,
// so they are not kept as history. The message they refer to is.
const FOLLOW = /\b(it|that|this|there|them|those|same|again|still)\b|^\s*(and|so|also|then|what about|how about)\b|هذا|هذه|ذلك|نفسه|نفسها|مرة أخرى|أيضا|ايضا|وماذا عن/i;
const TOPIC = /\b(grades?|marks?|gpa|results?|transcript|regist\w*|enrol\w*|drop\w*|semester|fees?|tuition|pay\w*|invoice|scholarship|refund|schedule|timetable|lectures?|class(es)? times?)\b|معدل|علام|درجات|نتيج|تسجيل|سحب|انسحاب|رسوم|دفع|قسط|فاتورة|جدول|محاضر/i;
const isFollowUpText = (t) => wordsOf(t).length <= 12 && FOLLOW.test(String(t)) && !TOPIC.test(String(t));

const rows = $input.all().map(i => i.json)
  .filter(r => String(r['Student Id'] ?? '').trim() === String(chat.id) && String(r['Massage'] ?? '').trim() !== '');
const useful = rows.filter(r => !isGreetingText(r['Massage']) && !isFollowUpText(r['Massage']));
// Only the latest earlier message is kept: a follow-up ("it", "that") refers to it, and two similar messages
// confuse the small model (it asks which of them is meant). Greetings and short follow-ups are skipped, so the
// message a chain of follow-ups points back to stays available.
const recent = useful.slice(-1);
const prev = recent.length ? recent[recent.length - 1] : null;
const fmt = (r) => {
  const when = String(r['TimeStamp'] || '').slice(0, 16).replace('T', ' ');
  return (when ? when + ' | ' : '') + String(r['Massage']).replace(/\s+/g, ' ').slice(0, 200);
};

// History is only handed to the AI when the current message needs it: a short message that points back
// ("Is there a deadline for it?") or does not name a topic of its own. A message that already states its topic
// ("I want to drop my Chemistry course", a long grade question) gets no history, because the small model
// otherwise mixes the old topic into the answer.
const nWords = wordsOf(text).length;
const needHistory = !isGreeting && (nWords <= 20 ? (FOLLOW.test(text) || !TOPIC.test(text)) : !TOPIC.test(text));
let history;
if (isGreeting) history = 'Not needed: the current message is only a greeting or a thank-you.';
else if (!needHistory) history = 'Not needed: the current message already states its own topic.';
else if (recent.length === 0) history = 'No earlier messages from this student.';
else history = '- Previous message (the one "it" or "that" usually refers to): ' + fmt(recent[0]);
// For a short follow-up that points back, tell the model outright what the topic is and ask it to name that topic.
if (needHistory && recent.length > 0 && nWords <= 20 && FOLLOW.test(text)) history += '\n- The current message is a short follow-up. The student is asking about: "' + String(recent[0]['Massage']).replace(/\s+/g, ' ').slice(0, 120) + '". Answer about exactly that and name the topic (for example the course or the fee) in your reply. Do not ask which topic is meant.';

// Follow-up routing: a short message that points back ("it", "that", "again") and names no topic of its own
// goes to the same specialist as the previous message, if that message was sent in the last 30 minutes.
const KNOWN = ['grade', 'registration', 'payment', 'schedule'];
const prevCat = prev ? String(prev['Category'] || '').trim().toLowerCase() : '';
const prevAge = prev ? Date.now() - Date.parse(prev['TimeStamp']) : Infinity;
let Category = v.Category;
let category_from_history = false;
if (!isGreeting && wordsOf(text).length <= 12 && FOLLOW.test(text) && !TOPIC.test(text) && KNOWN.includes(prevCat) && prevAge < 30 * 60 * 1000 && Category !== prevCat) {
  Category = prevCat;
  category_from_history = true;
}

// The reply language must follow the CURRENT message, not the history.
// Arabic only when the message is clearly Arabic; a mixed English + Arabic message gets an English reply.
const arabic = (text.match(/[\u0600-\u06FF]/g) || []).length;
const latin = (text.match(/[A-Za-z]/g) || []).length;
const reply_language = arabic > 2 * latin ? 'Arabic' : 'English';

return [{ json: { ...v, Category, category_from_history, history, history_count: rows.length, history_used: needHistory && recent.length > 0, reply_language }, pairedItem: { item: 0 } }];

const rows = $input.all().map(i => i.json).filter(r => r['Student Id'] !== undefined && String(r['Student Id']).trim() !== '');
const existing = rows.length ? rows[0] : null;
const count = existing ? (Number(existing.Count) || 1) + 1 : 1;
const chat = $('Telegram Trigger').first().json.message.chat;
return [{ json: { 'Student Id': String(chat.id), Key: String(chat.id) + '|urgent', Category: 'urgent', Count: String(count), Priority: 'HIGH', Date: $now.toISO(), isDuplicate: !!existing }, pairedItem: { item: 0 } }];

// Live exchange rates from the external API (HTTP Request node).
// The conversion itself is calculated here in code, because the small AI model is not reliable at arithmetic.
const r = $json.rates;
const msg = String($('Telegram Trigger').first().json.message.text || '');
let live = 'Live exchange rates are not available right now.';
let conversion = 'none';

if ($json.result === 'success' && r && r.USD) {
  const f = (c) => Number(r[c]).toFixed(3);
  live = '1 JOD = ' + f('USD') + ' USD, ' + f('EUR') + ' EUR, ' + f('SAR') + ' SAR, ' + f('AED') + ' AED (updated ' + $json.time_last_update_utc + ')';

  const WORDS = 'JOD|USD|EUR|SAR|AED|JD|dinars?|dollars?|euros?';
  const alias = { JD: 'JOD', DINAR: 'JOD', DINARS: 'JOD', DOLLAR: 'USD', DOLLARS: 'USD', EURO: 'EUR', EUROS: 'EUR' };
  const toCode = (w) => { const u = w.toUpperCase(); return alias[u] || u; };
  const text = msg.replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
  const m1 = text.match(new RegExp('(\\d[\\d,]*(?:\\.\\d+)?)\\s*(' + WORDS + ')\\b', 'i'));
  const m2 = text.match(new RegExp('\\b(' + WORDS + ')\\s*(\\d[\\d,]*(?:\\.\\d+)?)', 'i'));
  const found = m1 ? { amount: m1[1], code: m1[2] } : (m2 ? { amount: m2[2], code: m2[1] } : null);
  if (found) {
    const amount = Number(found.amount.replace(/,/g, ''));
    const src = toCode(found.code);
    const others = [...text.matchAll(new RegExp('\\b(' + WORDS + ')\\b', 'gi'))].map((x) => toCode(x[1])).filter((c) => c !== src && r[c]);
    const tgt = others[0] || (src === 'JOD' ? 'USD' : 'JOD');
    if (r[src] && r[tgt]) {
      conversion = amount + ' ' + src + ' = ' + (amount / r[src] * r[tgt]).toFixed(2) + ' ' + tgt;
    }
  }
}
// The rates are fetched for every payment message, but they are only handed to the AI
// when the student's message is about a currency or an exchange rate; otherwise the small model
// mentions currency conversion in answers that have nothing to do with it.
const aboutCurrency = /\b(JOD|USD|EUR|SAR|AED|JD|dinars?|dollars?|euros?|currency|currencies|exchange|convert|conversion)\b|دينار|دولار|يورو|ريال|درهم|عملة|العملات|صرف|تحويل/i.test(msg);
if (!aboutCurrency) { live = 'Not requested by the student.'; conversion = 'none'; }

// Fallback when the external service cannot be reached: the AI gets the exact reply to send,
// so a small model can never invent an exchange rate.
const ratesOk = $json.result === 'success' && r && r.USD;
const firstName = String($('Telegram Trigger').first().json.message.chat.first_name || '');
const isArabic = $('Build History').first().json.reply_language === 'Arabic';
const fallbackReply = isArabic
  ? 'مرحباً ' + firstName + '، سعر الصرف المباشر غير متاح حالياً. يرجى المحاولة بعد قليل أو التواصل مع قسم المالية على finance@example.edu.'
  : 'Hi ' + firstName + ', the live exchange rate is not available right now. Please try again in a few minutes or contact the finance office at finance@example.edu.';
// Text block handed to the payment AI. It is empty for questions that are not about currency.
const rates_block = !aboutCurrency ? '' : !ratesOk ?
  'IMPORTANT: the live exchange-rate service is down, so you do NOT know any exchange rate. Do not state any rate or converted amount. Reply with exactly this message and nothing else: "' + fallbackReply + '"' :
  'Live exchange rates from an external service: ' + live + '\n' +
  'Converted amount (already calculated, copy it exactly): ' + conversion + '\n' +
  'Rule for this question: copy the converted amount exactly as written, without mentioning how it was calculated (never do your own arithmetic) and say it is an approximate live rate, not an official university rate. If the pre-calculated conversion is "none", quote only the rates above. If the rates are not available, say so and point the student to the finance office. Never invent rates or fees.';

return [{ json: { live_rates: live, conversion, rates_block, rates_ok: $json.result === 'success', currency_question: aboutCurrency }, pairedItem: { item: 0 } }];
